window.LESSONS = [{"id": "l1", "num": 1, "title": "Best Days and Worst Days", "titleFr": "Meilleurs jours et pires jours", "speaker": "Emily Belle Freeman", "role": "Présidente générale des Jeunes Filles", "source": "Conférence générale · Avril 2026", "theme": "Grâce à Jésus-Christ, peu importe la situation actuelle, tes meilleurs jours sont à venir.", "parts": [{"id": "l1p1", "num": 1, "title": "Meilleurs jours, pires jours", "sub": "L'histoire d'Emily et Greg", "emoji": "🌗", "audio": "https://assets.churchofjesuschrist.org/399xzzcdtaxbyusiq3w6e5yn12mo8s0to58bzv1v-128k-en.mp3", "dur": 52.4, "sentences": [{"en": "Several weeks ago we began planning our daughter's wedding.", "fr": "Il y a plusieurs semaines, nous avons commencé à préparer le mariage de notre fille.", "s": 0.0, "e": 5.12, "vocab": [["wedding", "mariage"], ["to plan", "préparer, planifier"]]}, {"en": "With great joy, we dreamed and brainstormed as we considered all the options.", "fr": "Avec une grande joie, nous avons rêvé et réfléchi en considérant toutes les options.", "s": 5.12, "e": 10.48, "vocab": [["to brainstorm", "chercher des idées ensemble"], ["joy", "joie"]]}, {"en": "And then my husband, Greg, received a phone call he couldn't ignore.", "fr": "Et puis mon mari, Greg, a reçu un appel téléphonique qu'il ne pouvait pas ignorer.", "s": 10.48, "e": 15.12, "vocab": [["phone call", "appel téléphonique"], ["to ignore", "ignorer"]]}, {"en": "It was the oncologist confirming what we hoped wasn't true.", "fr": "C'était l'oncologue qui confirmait ce que nous espérions être faux.", "s": 15.12, "e": 18.88, "vocab": [["oncologist", "oncologue (médecin du cancer)"], ["to hope", "espérer"]]}, {"en": "Greg's cancer had returned.", "fr": "Le cancer de Greg était revenu.", "s": 18.88, "e": 21.64, "vocab": [["cancer", "cancer"], ["returned", "revenu"]]}, {"en": "Isn't it amazing how you can go from best day to worst day in a matter of minutes?", "fr": "N'est-ce pas étonnant de voir comment on peut passer du meilleur jour au pire jour en quelques minutes ?", "s": 21.64, "e": 27.44, "vocab": [["amazing", "étonnant"], ["in a matter of minutes", "en quelques minutes"]]}, {"en": "This is mortality.", "fr": "C'est cela, la condition mortelle.", "s": 27.44, "e": 28.96, "vocab": [["mortality", "la condition mortelle, la vie terrestre"]]}, {"en": "A proving ground.", "fr": "Un terrain d'épreuve.", "s": 28.96, "e": 30.2, "vocab": [["proving ground", "terrain d'épreuve"]]}, {"en": "A place designed for growth.", "fr": "Un lieu conçu pour grandir.", "s": 30.2, "e": 32.68, "vocab": [["designed", "conçu"], ["growth", "croissance"]]}, {"en": "I have learned that God allows mortality to do its work in us—and that includes both best days and worst days.", "fr": "J'ai appris que Dieu permet à la condition mortelle d'accomplir son œuvre en nous — et cela inclut les meilleurs jours comme les pires.", "s": 32.68, "e": 41.84, "vocab": [["to allow", "permettre"], ["to include", "inclure"]]}, {"en": "How do we get through those days?", "fr": "Comment traverser ces jours-là ?", "s": 41.84, "e": 44.2, "vocab": [["to get through", "traverser, surmonter"]]}, {"en": "The story of Peter teaches us that strength comes as we walk with Christ and hold fast to His eternal truths.", "fr": "L'histoire de Pierre nous enseigne que la force vient quand nous marchons avec le Christ et nous attachons fermement à ses vérités éternelles.", "s": 44.2, "e": 52.4, "vocab": [["strength", "force"], ["to hold fast", "s'attacher fermement"]]}]}, {"id": "l1p2", "num": 2, "title": "Vérités éternelles", "sub": "« Tu es le Christ »", "emoji": "⭐", "audio": "https://assets.churchofjesuschrist.org/399xzzcdtaxbyusiq3w6e5yn12mo8s0to58bzv1v-128k-en.mp3", "dur": 87.8, "sentences": [{"en": "When Jesus came into the coasts of Caesarea Philippi, he asked his disciples, whom say ye that I am?", "fr": "« Quand Jésus arriva dans le territoire de Césarée de Philippe, il demanda à ses disciples : qui dites-vous que je suis ? »", "s": 52.4, "e": 60.24, "vocab": [["coasts", "territoire, région"], ["whom say ye", "qui dites-vous (anglais ancien)"]]}, {"en": "They had seen empty nets filled, storms at sea calmed, loaves multiplied, and the dead raised.", "fr": "Ils avaient vu des filets vides se remplir, des tempêtes en mer se calmer, des pains se multiplier et des morts ressusciter.", "s": 60.24, "e": 67.2, "vocab": [["net", "filet"], ["loaves", "pains"], ["the dead raised", "les morts ressuscités"]]}, {"en": "When Peter answered, Thou art the Christ, the Son of the living God,", "fr": "Quand Pierre répondit : « Tu es le Christ, le Fils du Dieu vivant »,", "s": 67.2, "e": 72.68, "vocab": [["thou art", "tu es (anglais ancien)"], ["living", "vivant"]]}, {"en": "Jesus responded, Blessed art thou, Simon: flesh and blood hath not revealed it unto thee, but my Father which is in heaven.", "fr": "Jésus répondit : « Tu es bienheureux, Simon : ce ne sont pas la chair et le sang qui t'ont révélé cela, mais c'est mon Père qui est dans les cieux. »", "s": 72.68, "e": 81.56, "vocab": [["flesh and blood", "la chair et le sang"], ["to reveal", "révéler"]]}, {"en": "That day must have felt like a best day.", "fr": "Ce jour-là a dû ressembler à un meilleur jour.", "s": 81.56, "e": 85.48, "vocab": [["must have felt", "a dû sembler"]]}, {"en": "The Spirit confirmed an eternal truth, and Peter courageously bore testimony of it.", "fr": "L'Esprit a confirmé une vérité éternelle, et Pierre en a courageusement rendu témoignage.", "s": 85.48, "e": 92.32, "vocab": [["to confirm", "confirmer"], ["to bear testimony", "rendre témoignage"]]}, {"en": "But only three verses later, a shift occurred.", "fr": "Mais seulement trois versets plus loin, un changement s'est produit.", "s": 92.32, "e": 95.28, "vocab": [["verse", "verset"], ["a shift occurred", "un changement s'est produit"]]}, {"en": "As Jesus began to speak of His coming death, Peter rebuked Him, saying, This shall not be.", "fr": "Quand Jésus a commencé à parler de sa mort prochaine, Pierre l'a repris en disant : « Cela ne t'arrivera pas. »", "s": 95.28, "e": 102.2, "vocab": [["to rebuke", "reprendre, réprimander"], ["coming death", "mort prochaine"]]}, {"en": "Get thee behind me, Satan, was the Savior's immediate response.", "fr": "« Arrière de moi, Satan », fut la réponse immédiate du Sauveur.", "s": 102.2, "e": 106.8, "vocab": [["get thee behind me", "arrière de moi (anglais ancien)"], ["immediate", "immédiate"]]}, {"en": "Peter had good intentions—he didn't want the Savior to die—but he misunderstood God's plan for His Son.", "fr": "Pierre avait de bonnes intentions — il ne voulait pas que le Sauveur meure — mais il avait mal compris le plan de Dieu pour son Fils.", "s": 106.8, "e": 115.52, "vocab": [["intentions", "intentions"], ["to misunderstand", "mal comprendre"]]}, {"en": "Peter's story went from best day to worst day in a matter of three verses.", "fr": "L'histoire de Pierre est passée du meilleur jour au pire jour en l'espace de trois versets.", "s": 115.52, "e": 122.12, "vocab": [["in a matter of", "en l'espace de"]]}, {"en": "From Peter's story we learn that our understanding of eternal truth is not forged in a single moment—", "fr": "De l'histoire de Pierre, nous apprenons que notre compréhension de la vérité éternelle ne se forge pas en un seul instant —", "s": 122.12, "e": 129.0, "vocab": [["to forge", "forger"], ["a single moment", "un seul instant"]]}, {"en": "testimony is built over time, day after day, both best days and worst.", "fr": "le témoignage se construit avec le temps, jour après jour, dans les meilleurs jours comme dans les pires.", "s": 129.0, "e": 136.36, "vocab": [["is built", "se construit"], ["over time", "avec le temps"]]}, {"en": "Those eternal truths are often proven through invitation.", "fr": "Ces vérités éternelles sont souvent éprouvées par des invitations.", "s": 136.36, "e": 140.16, "vocab": [["proven", "éprouvées, mises à l'épreuve"]]}]}, {"id": "l1p3", "num": 3, "title": "Marcher sur l'eau", "sub": "L'invitation : « Viens »", "emoji": "🌊", "audio": "https://assets.churchofjesuschrist.org/399xzzcdtaxbyusiq3w6e5yn12mo8s0to58bzv1v-128k-en.mp3", "dur": 68.0, "sentences": [{"en": "In Matthew 14, Peter and the other disciples were caught in a storm when Jesus approached the ship.", "fr": "Dans Matthieu 14, Pierre et les autres disciples étaient pris dans une tempête quand Jésus s'est approché de la barque.", "s": 140.16, "e": 146.16, "vocab": [["caught in a storm", "pris dans une tempête"], ["to approach", "s'approcher"]]}, {"en": "Peter cried out, Lord, if it be thou, bid me come unto thee on the water.", "fr": "Pierre s'écria : « Seigneur, si c'est toi, ordonne que j'aille vers toi sur les eaux. »", "s": 146.16, "e": 151.36, "vocab": [["to cry out", "s'écrier"], ["bid me come", "ordonne que je vienne (ancien)"]]}, {"en": "And Jesus answered with an invitation: Come.", "fr": "Et Jésus répondit par une invitation : « Viens. »", "s": 151.36, "e": 155.28, "vocab": [["to answer", "répondre"]]}, {"en": "So Peter stepped out of the boat.", "fr": "Alors Pierre sortit de la barque.", "s": 155.28, "e": 157.72, "vocab": [["to step out", "sortir, descendre"], ["boat", "barque, bateau"]]}, {"en": "He walked on the water, to go to Jesus.", "fr": "« Il marcha sur les eaux pour aller vers Jésus. »", "s": 157.72, "e": 161.8, "vocab": [["to walk on the water", "marcher sur les eaux"]]}, {"en": "Best day.", "fr": "Meilleur jour.", "s": 161.8, "e": 162.52, "vocab": [["best", "meilleur"]]}, {"en": "But in the very next verse, we read that Peter saw the wind, became afraid, and began to sink.", "fr": "Mais au verset suivant, nous lisons que Pierre vit le vent, eut peur et commença à s'enfoncer.", "s": 162.52, "e": 169.16, "vocab": [["wind", "vent"], ["afraid", "effrayé"], ["to sink", "couler, s'enfoncer"]]}, {"en": "Worst day in a matter of moments.", "fr": "Pire jour en quelques instants.", "s": 169.16, "e": 171.8, "vocab": [["moment", "instant"]]}, {"en": "Have you ever accepted an invitation from the Lord and then felt unequal to the task?", "fr": "As-tu déjà accepté une invitation du Seigneur pour ensuite te sentir incapable d'y répondre ?", "s": 171.8, "e": 177.16, "vocab": [["unequal to the task", "pas à la hauteur de la tâche"]]}, {"en": "We all know what it is to doubt, to experience sinking moments.", "fr": "Nous savons tous ce que c'est que douter, que vivre des moments où l'on s'enfonce.", "s": 177.16, "e": 182.08, "vocab": [["to doubt", "douter"], ["sinking", "qui s'enfonce"]]}, {"en": "But notice where Jesus was when Peter accepted the invitation that seemed too big.", "fr": "Mais remarque où était Jésus quand Pierre a accepté cette invitation qui semblait trop grande.", "s": 182.08, "e": 187.32, "vocab": [["to notice", "remarquer"], ["too big", "trop grand(e)"]]}, {"en": "He wasn't shouting instructions from the shore or offering advice from the safety of the boat.", "fr": "Il ne criait pas des instructions depuis le rivage et ne donnait pas de conseils depuis la sécurité de la barque.", "s": 187.32, "e": 193.52, "vocab": [["to shout", "crier"], ["shore", "rivage"], ["advice", "conseils"]]}, {"en": "He was in the water—with Peter.", "fr": "Il était dans l'eau — avec Pierre.", "s": 193.52, "e": 196.96, "vocab": [["water", "eau"]]}, {"en": "Within reaching distance.", "fr": "À portée de main.", "s": 196.96, "e": 199.6, "vocab": [["within reaching distance", "à portée de main"]]}, {"en": "As you accept the Lord's invitations, on both your best days and your worst, the same will be true for you.", "fr": "Quand tu acceptes les invitations du Seigneur, dans tes meilleurs jours comme dans tes pires jours, il en sera de même pour toi.", "s": 199.6, "e": 208.12, "vocab": [["to accept", "accepter"], ["true", "vrai"]]}]}, {"id": "l1p4", "num": 4, "title": "Le regard du Sauveur", "sub": "La nuit la plus sombre de Pierre", "emoji": "💙", "audio": "https://assets.churchofjesuschrist.org/399xzzcdtaxbyusiq3w6e5yn12mo8s0to58bzv1v-128k-en.mp3", "dur": 62.2, "sentences": [{"en": "Now let's consider one final story.", "fr": "Considérons maintenant une dernière histoire.", "s": 208.12, "e": 211.32, "vocab": [["to consider", "considérer, examiner"], ["final", "dernier, dernière"]]}, {"en": "This time, let's begin with the worst day.", "fr": "Cette fois, commençons par le pire jour.", "s": 211.32, "e": 214.92, "vocab": [["worst", "pire"]]}, {"en": "On the night Christ was arrested, Peter denied knowing Him three times, and then the rooster crowed.", "fr": "La nuit où le Christ fut arrêté, Pierre nia le connaître trois fois, puis le coq chanta.", "s": 214.92, "e": 221.04, "vocab": [["arrested", "arrêté"], ["to deny", "nier"], ["rooster crowed", "le coq a chanté"]]}, {"en": "Luke writes, The Lord turned, and looked upon Peter.", "fr": "Luc écrit : « Le Seigneur, s'étant retourné, regarda Pierre. »", "s": 221.04, "e": 224.92, "vocab": [["to turn", "se retourner"], ["to look upon", "poser son regard sur"]]}, {"en": "I often think about that look.", "fr": "Je pense souvent à ce regard.", "s": 224.92, "e": 227.88, "vocab": [["look", "regard"]]}, {"en": "Jesus knew the worst wasn't over.", "fr": "Jésus savait que le pire n'était pas passé.", "s": 227.88, "e": 230.04, "vocab": [["over", "fini, terminé"]]}, {"en": "He knew there were very hard experiences ahead.", "fr": "Il savait que des expériences très difficiles attendaient.", "s": 230.04, "e": 233.16, "vocab": [["ahead", "devant, à venir"]]}, {"en": "When Peter saw that look, Luke tells us he remembered the warning from Jesus about the cock crowing.", "fr": "Quand Pierre a vu ce regard, Luc nous dit qu'il s'est souvenu de l'avertissement de Jésus au sujet du chant du coq.", "s": 233.16, "e": 240.08, "vocab": [["warning", "avertissement"], ["to remember", "se souvenir"]]}, {"en": "I can't help but wonder if Jesus was remembering the encouraging words He had spoken to Peter earlier that day:", "fr": "Je ne peux pas m'empêcher de me demander si Jésus se souvenait des paroles d'encouragement qu'il avait dites à Pierre plus tôt ce jour-là :", "s": 240.08, "e": 248.0, "vocab": [["to wonder", "se demander"], ["encouraging", "encourageant(es)"]]}, {"en": "I have prayed for thee, that thy faith fail not: and when thou art converted, strengthen thy brethren.", "fr": "« J'ai prié pour toi, afin que ta foi ne défaille point ; et toi, quand tu seras converti, affermis tes frères. »", "s": 248.0, "e": 257.2, "vocab": [["fail not", "ne défaille pas"], ["to strengthen", "fortifier, affermir"], ["brethren", "frères"]]}, {"en": "Perhaps that look was not a look of failure but instead a look of enabling strength meant to carry Peter through the worst moments ahead:", "fr": "Peut-être que ce regard n'était pas un regard d'échec, mais un regard de force habilitante destiné à porter Pierre à travers les pires moments à venir :", "s": 257.2, "e": 266.52, "vocab": [["failure", "échec"], ["enabling strength", "force habilitante"]]}, {"en": "The trial. The cross. The tomb.", "fr": "Le procès. La croix. Le tombeau.", "s": 266.52, "e": 270.36, "vocab": [["trial", "procès"], ["cross", "croix"], ["tomb", "tombeau"]]}]}, {"id": "l1p5", "num": 5, "title": "Pais mes brebis", "sub": "Sur le rivage de Galilée", "emoji": "🐑", "audio": "https://assets.churchofjesuschrist.org/399xzzcdtaxbyusiq3w6e5yn12mo8s0to58bzv1v-128k-en.mp3", "dur": 44.5, "sentences": [{"en": "After those hard days had passed, and after a long night of fishing, Peter and Jesus stood on the shore of Galilee.", "fr": "Une fois ces jours difficiles passés, et après une longue nuit de pêche, Pierre et Jésus se tenaient sur le rivage de la mer de Galilée.", "s": 270.36, "e": 278.44, "vocab": [["fishing", "pêche"], ["shore", "rivage"]]}, {"en": "On that day the Savior extended another invitation: Feed my sheep.", "fr": "Ce jour-là, le Sauveur lança une autre invitation : « Pais mes brebis. »", "s": 278.44, "e": 283.32, "vocab": [["to extend an invitation", "adresser une invitation"], ["feed my sheep", "pais mes brebis"]]}, {"en": "Peter's faith hadn't failed, and because of his deep love for Jesus Christ, there was still a great work in store for him.", "fr": "La foi de Pierre n'avait pas défailli, et grâce à son amour profond pour Jésus-Christ, une grande œuvre l'attendait encore.", "s": 283.32, "e": 293.2, "vocab": [["deep love", "amour profond"], ["in store", "en réserve, à venir"]]}, {"en": "Peter was to be more than just a fisherman; he would now become a shepherd.", "fr": "Pierre allait être bien plus qu'un pêcheur ; il allait maintenant devenir un berger.", "s": 293.2, "e": 298.96, "vocab": [["fisherman", "pêcheur"], ["shepherd", "berger"]]}, {"en": "Sometimes we may wonder if the Lord's promises will truly be fulfilled in us—especially when all seems lost.", "fr": "Parfois, nous nous demandons si les promesses du Seigneur s'accompliront vraiment en nous — surtout quand tout semble perdu.", "s": 298.96, "e": 307.76, "vocab": [["promise", "promesse"], ["fulfilled", "accomplies"], ["lost", "perdu"]]}, {"en": "Especially on our worst days.", "fr": "Surtout dans nos pires jours.", "s": 307.76, "e": 310.6, "vocab": [["especially", "surtout, particulièrement"]]}, {"en": "Peter's story reminds us that they will.", "fr": "L'histoire de Pierre nous rappelle qu'elles s'accompliront.", "s": 310.6, "e": 314.84, "vocab": [["to remind", "rappeler"]]}]}, {"id": "l1p6", "num": 6, "title": "Deux vérités sur Pierre", "sub": "Et un conseil pour toi", "emoji": "📖", "audio": "https://assets.churchofjesuschrist.org/399xzzcdtaxbyusiq3w6e5yn12mo8s0to58bzv1v-128k-en.mp3", "dur": 63.9, "sentences": [{"en": "History could suggest that Peter was a man who tried to stand in the way of the Father's plan,", "fr": "L'histoire pourrait laisser entendre que Pierre était un homme qui a essayé de se mettre en travers du plan du Père,", "s": 314.84, "e": 320.48, "vocab": [["to suggest", "laisser entendre"], ["to stand in the way", "se mettre en travers"]]}, {"en": "who nearly drowned because of lack of faith, and who denied knowing the Savior three times—and that would be true.", "fr": "qui a failli se noyer par manque de foi, et qui a nié connaître le Sauveur trois fois — et ce serait vrai.", "s": 320.48, "e": 328.28, "vocab": [["nearly drowned", "a failli se noyer"], ["lack of faith", "manque de foi"]]}, {"en": "But it is also true that Peter walked on water,", "fr": "Mais il est aussi vrai que Pierre a marché sur l'eau,", "s": 328.28, "e": 331.88, "vocab": [["also", "aussi"]]}, {"en": "he was the first Apostle to bear witness that Jesus Christ is the Son of God,", "fr": "qu'il a été le premier apôtre à témoigner que Jésus-Christ est le Fils de Dieu,", "s": 331.88, "e": 337.04, "vocab": [["to bear witness", "témoigner"]]}, {"en": "and he was given priesthood keys to preside over the Lord's Church.", "fr": "et qu'il a reçu les clés de la prêtrise pour présider l'Église du Seigneur.", "s": 337.04, "e": 341.64, "vocab": [["priesthood keys", "clés de la prêtrise"], ["to preside", "présider"]]}, {"en": "And maybe it took both the worst days and the best days for Peter to become who the Lord needed him to become.", "fr": "Et peut-être qu'il a fallu à la fois les pires jours et les meilleurs jours pour que Pierre devienne celui que le Seigneur avait besoin qu'il devienne.", "s": 341.64, "e": 350.88, "vocab": [["to become", "devenir"]]}, {"en": "I don't know what your story looks like right now, if today is a best day or a worst day.", "fr": "Je ne sais pas à quoi ressemble ton histoire en ce moment, si aujourd'hui est un meilleur jour ou un pire jour.", "s": 350.88, "e": 356.4, "vocab": [["story", "histoire"], ["right now", "en ce moment"]]}, {"en": "But here is my advice for you.", "fr": "Mais voici mon conseil pour toi.", "s": 356.4, "e": 359.52, "vocab": [["advice", "conseil"]]}, {"en": "On that worst day with Greg several weeks ago, I opened my For the Strength of Youth guide,", "fr": "En ce pire jour avec Greg, il y a plusieurs semaines, j'ai ouvert mon guide Pour la force de la jeunesse,", "s": 359.52, "e": 365.24, "vocab": [["guide", "guide"], ["to open", "ouvrir"]]}, {"en": "wondering if the eternal truths, invitations, and promised blessings from the guide could really help Greg and me find strength in Christ.", "fr": "en me demandant si les vérités éternelles, les invitations et les bénédictions promises du guide pouvaient vraiment nous aider, Greg et moi, à trouver de la force dans le Christ.", "s": 365.24, "e": 375.0, "vocab": [["blessing", "bénédiction"], ["to find strength", "trouver de la force"]]}, {"en": "Here is what I read.", "fr": "Voici ce que j'ai lu.", "s": 375.0, "e": 376.64, "vocab": [["to read", "lire"]]}, {"en": "Maybe these words will help you.", "fr": "Peut-être que ces paroles t'aideront aussi.", "s": 376.64, "e": 378.72, "vocab": [["words", "paroles, mots"]]}]}, {"id": "l1p7", "num": 7, "title": "Un guide pour la force", "sub": "Jeunes, soyez forts", "emoji": "💪", "audio": "https://assets.churchofjesuschrist.org/399xzzcdtaxbyusiq3w6e5yn12mo8s0to58bzv1v-128k-en.mp3", "dur": 81.6, "sentences": [{"en": "God's plan is for you. He has all power and knows all things. You can trust Him, even when life is hard.", "fr": "« Le plan de Dieu est pour toi. Il a tout pouvoir et connaît toutes choses. Tu peux lui faire confiance, même quand la vie est dure. »", "s": 378.72, "e": 387.84, "vocab": [["to trust", "faire confiance"], ["hard", "dur, difficile"]]}, {"en": "God wants to communicate with you. He knows you. He knows your name.", "fr": "« Dieu veut communiquer avec toi. » Il te connaît. Il connaît ton nom.", "s": 387.84, "e": 393.36, "vocab": [["to communicate", "communiquer"], ["name", "nom"]]}, {"en": "Pour out your heart to Him. Be still and listen for His answers.", "fr": "« Épanche ton cœur devant lui. Sois tranquille et écoute ses réponses. »", "s": 393.36, "e": 398.92, "vocab": [["pour out your heart", "épanche ton cœur"], ["be still", "sois tranquille"]]}, {"en": "Jesus Christ will help you. When you are worried, afraid, or struggle in any way, He will comfort you.", "fr": "« Jésus-Christ t'aidera. Quand tu es inquiet, effrayé ou en difficulté de quelque manière que ce soit, il te consolera. »", "s": 398.92, "e": 407.44, "vocab": [["worried", "inquiet"], ["to comfort", "consoler"]]}, {"en": "Walk in God's light. You make better choices when you can see things clearly.", "fr": "« Marche dans la lumière de Dieu. Tu fais de meilleurs choix quand tu vois les choses clairement. »", "s": 407.44, "e": 413.12, "vocab": [["light", "lumière"], ["choice", "choix"], ["clearly", "clairement"]]}, {"en": "Temple ordinances and covenants give you greater access to God's blessings,", "fr": "« Les ordonnances et les alliances du temple te donnent un plus grand accès aux bénédictions de Dieu »,", "s": 413.12, "e": 418.08, "vocab": [["ordinance", "ordonnance"], ["covenant", "alliance"], ["access", "accès"]]}, {"en": "help you navigate your life with divine guidance, increase your companionship with the Spirit and with angels,", "fr": "t'aident à diriger ta vie avec l'aide divine, augmentent ta compagnie de l'Esprit et des anges,", "s": 418.08, "e": 425.48, "vocab": [["to navigate", "diriger, naviguer"], ["companionship", "compagnie"]]}, {"en": "and enable you to live up to your privileges and draw upon the power of God.", "fr": "et te permettent d'être à la hauteur de tes privilèges et de puiser dans le pouvoir de Dieu.", "s": 425.48, "e": 430.64, "vocab": [["privilege", "privilège"], ["to draw upon", "puiser dans"]]}, {"en": "Finally, Jesus Christ brings joy. You might have a bad day, a bad week, or a bad year.", "fr": "Enfin : « Jésus-Christ apporte la joie. Tu auras peut-être une mauvaise journée, une mauvaise semaine ou une mauvaise année. »", "s": 430.64, "e": 438.48, "vocab": [["joy", "joie"], ["bad week", "mauvaise semaine"]]}, {"en": "Just remember, joy is not the absence of sorrow in your life; it is the presence of Jesus Christ in your life.", "fr": "« Souviens-toi : la joie n'est pas l'absence de tristesse dans ta vie ; c'est la présence de Jésus-Christ dans ta vie. »", "s": 438.48, "e": 448.04, "vocab": [["absence", "absence"], ["sorrow", "tristesse"], ["presence", "présence"]]}, {"en": "As you spend time in this guide, you will begin to realize that this is not just a guide for standards; this is a guide for strength.", "fr": "En passant du temps dans ce guide, tu commenceras à comprendre que ce n'est pas seulement un guide de normes : c'est un guide de force.", "s": 448.04, "e": 460.36, "vocab": [["standard", "norme"], ["strength", "force"]]}]}, {"id": "l1p8", "num": 8, "title": "Tes meilleurs jours sont à venir", "sub": "Le témoignage final", "emoji": "🌅", "audio": "https://assets.churchofjesuschrist.org/399xzzcdtaxbyusiq3w6e5yn12mo8s0to58bzv1v-128k-en.mp3", "dur": 46.5, "sentences": [{"en": "Because Jesus Christ knows all about best days and worst days:", "fr": "Parce que Jésus-Christ connaît tout des meilleurs jours et des pires jours :", "s": 460.36, "e": 465.04, "vocab": [["to know all about", "tout connaître de"]]}, {"en": "suffering so great that an angel was sent to strengthen Him, the betrayal of a good friend, the cross on Calvary.", "fr": "une souffrance si grande qu'un ange fut envoyé pour le fortifier, la trahison d'un bon ami, la croix du Calvaire.", "s": 465.04, "e": 474.2, "vocab": [["suffering", "souffrance"], ["betrayal", "trahison"], ["angel", "ange"]]}, {"en": "But His story also has a garden, a stone rolled away, and an empty tomb.", "fr": "Mais son histoire comporte aussi un jardin, une pierre roulée de côté et un tombeau vide.", "s": 474.2, "e": 481.32, "vocab": [["stone rolled away", "pierre roulée de côté"], ["empty tomb", "tombeau vide"]]}, {"en": "Because of Him, no matter how bad things are right now, your best days are ahead.", "fr": "Grâce à lui, peu importe la gravité de ta situation actuelle, tes meilleurs jours sont à venir.", "s": 481.32, "e": 489.52, "vocab": [["no matter how", "peu importe à quel point"], ["ahead", "à venir"]]}, {"en": "Jesus Christ is our strength. This I know.", "fr": "Jésus-Christ est notre force. Je le sais.", "s": 489.52, "e": 497.92, "vocab": [["strength", "force"]]}, {"en": "Of this I bear witness in the name of Jesus Christ, amen.", "fr": "J'en rends témoignage au nom de Jésus-Christ, amen.", "s": 497.92, "e": 506.88, "vocab": [["to bear witness", "rendre témoignage"], ["in the name of", "au nom de"]]}]}]}, {"id": "l2", "num": 2, "title": "Ministering: as I Have Loved You", "titleFr": "Servir : comme je vous ai aimés", "speaker": "Kristin M. Yee", "role": "Deuxième conseillère, présidence générale de la Société de Secours", "source": "Conférence générale · Avril 2026", "theme": "Servir, c'est aimer comme le Sauveur : une manière d'être qui apporte guérison et joie.", "parts": [{"id": "l2p1", "num": 1, "title": "L'histoire de mon père", "sub": "Deux frères qui n'ont pas jugé", "emoji": "🌱", "audio": "audio-lesson2.mp3", "dur": 41.1, "sentences": [{"en": "In my first general conference message, I briefly shared how the transformative power of the Savior's Atonement changed my father.", "fr": "Dans mon premier message de conférence générale, j'ai brièvement raconté comment le pouvoir transformateur de l'Expiation du Sauveur a changé mon père.", "s": 0.0, "e": 11.04, "vocab": [["briefly", "brièvement"], ["to change", "changer"]]}, {"en": "Today I would like to tell you a little more about how that change began.", "fr": "Aujourd'hui, j'aimerais te raconter un peu plus comment ce changement a commencé.", "s": 11.04, "e": 15.88, "vocab": [["today", "aujourd'hui"], ["to begin", "commencer"]]}, {"en": "My father hit a very low point in his life when two ministering brothers began to visit him.", "fr": "Mon père a touché le fond de sa vie quand deux frères chargés de veiller sur lui ont commencé à lui rendre visite.", "s": 15.88, "e": 21.32, "vocab": [["low point", "point le plus bas"], ["to visit", "rendre visite"]]}, {"en": "One of them invited my father to come with him and his wife to the temple.", "fr": "L'un d'eux a invité mon père à venir au temple avec lui et sa femme.", "s": 21.32, "e": 25.68, "vocab": [["to invite", "inviter"], ["wife", "épouse"]]}, {"en": "He accepted the invitation.", "fr": "Il a accepté l'invitation.", "s": 25.68, "e": 28.08, "vocab": [["to accept", "accepter"]]}, {"en": "Each week they picked him up and drove to the next city to worship and serve in the house of the Lord.", "fr": "Chaque semaine, ils passaient le prendre et conduisaient jusqu'à la ville voisine pour adorer et servir dans la maison du Seigneur.", "s": 28.08, "e": 34.08, "vocab": [["each week", "chaque semaine"], ["to drive", "conduire"]]}, {"en": "This continued for three years.", "fr": "Cela a continué pendant trois ans.", "s": 34.08, "e": 37.44, "vocab": [["to continue", "continuer"], ["three years", "trois ans"]]}, {"en": "Then my dad decided to become a temple worker.", "fr": "Puis mon papa a décidé de devenir servant du temple.", "s": 37.44, "e": 41.08, "vocab": [["to decide", "décider"], ["to become", "devenir"]]}]}, {"id": "l2p2", "num": 2, "title": "Un changement réel", "sub": "L'Esprit revenu dans une vie", "emoji": "✨", "audio": "audio-lesson2.mp3", "dur": 47.6, "sentences": [{"en": "I remember seeing changes in my father during that time.", "fr": "Je me souviens d'avoir vu des changements chez mon père pendant cette période.", "s": 41.08, "e": 45.04, "vocab": [["to remember", "se souvenir"], ["changes", "changements"]]}, {"en": "He became aware and attentive to the needs of others.", "fr": "Il est devenu conscient et attentif aux besoins des autres.", "s": 45.04, "e": 48.36, "vocab": [["aware", "conscient"], ["needs", "besoins"]]}, {"en": "He took better care of his health.", "fr": "Il a pris davantage soin de sa santé.", "s": 48.36, "e": 50.64, "vocab": [["health", "santé"], ["to take care", "prendre soin"]]}, {"en": "He began to care about his relationship with God and subsequently all the relationships in his life.", "fr": "Il a commencé à se soucier de sa relation avec Dieu, puis de toutes les relations de sa vie.", "s": 50.64, "e": 57.2, "vocab": [["relationship", "relation"], ["to care about", "se soucier de"]]}, {"en": "The change was real.", "fr": "Le changement était réel.", "s": 57.2, "e": 59.16, "vocab": [["real", "réel"]]}, {"en": "He now had the Spirit with him, and I felt it.", "fr": "Il avait maintenant l'Esprit avec lui, et je le sentais.", "s": 59.16, "e": 62.76, "vocab": [["now", "maintenant"], ["to feel", "sentir"]]}, {"en": "Bless this ministering couple for helping my dad.", "fr": "Que ce couple au service des autres soit béni d'avoir aidé mon papa.", "s": 62.76, "e": 66.36, "vocab": [["couple", "couple"], ["to help", "aider"]]}, {"en": "They didn't judge him for where he was in his life.", "fr": "Ils ne l'ont pas jugé pour là où il en était dans sa vie.", "s": 66.36, "e": 69.32, "vocab": [["to judge", "juger"]]}, {"en": "They walked with him and helped him to develop his relationship with God.", "fr": "Ils ont marché avec lui et l'ont aidé à développer sa relation avec Dieu.", "s": 69.32, "e": 73.8, "vocab": [["to walk", "marcher"], ["to develop", "développer"]]}, {"en": "They are still my father's closest and dearest friends.", "fr": "Ils sont encore aujourd'hui les amis les plus proches et les plus chers de mon père.", "s": 73.8, "e": 77.88, "vocab": [["closest", "les plus proches"], ["dear", "cher"]]}, {"en": "Because these humble and devoted disciples of the Savior quietly ministered to a seemingly lost and dejected man, my family and I have been eternally blessed.", "fr": "Parce que ces disciples humbles et dévoués du Sauveur ont discrètement servi un homme qui semblait perdu et abattu, ma famille et moi sommes bénis pour l'éternité.", "s": 77.88, "e": 88.68, "vocab": [["humble", "humble"], ["lost", "perdu"], ["dejected", "abattu"]]}]}, {"id": "l2p3", "num": 3, "title": "Les mains du Sauveur", "sub": "Bénir le père de quelqu'un", "emoji": "🤲", "audio": "audio-lesson2.mp3", "dur": 52.3, "sentences": [{"en": "When we choose to minister in our inspired assignments and our daily interactions,", "fr": "Quand nous choisissons de servir dans nos tâches inspirées et nos échanges quotidiens,", "s": 88.68, "e": 93.04, "vocab": [["to choose", "choisir"], ["daily", "quotidien"]]}, {"en": "we are helping to bless someone's father, someone's sister, someone's son.", "fr": "nous aidons à bénir le père de quelqu'un, la sœur de quelqu'un, le fils de quelqu'un.", "s": 93.04, "e": 99.52, "vocab": [["someone", "quelqu'un"], ["son", "fils"]]}, {"en": "When we minister, we are helping to answer each other's prayers.", "fr": "Quand nous servons, nous aidons à répondre aux prières les uns des autres.", "s": 99.52, "e": 103.44, "vocab": [["prayer", "prière"], ["to answer", "répondre"]]}, {"en": "We are the Savior's hands.", "fr": "Nous sommes les mains du Sauveur.", "s": 103.44, "e": 106.32, "vocab": [["hands", "mains"]]}, {"en": "Oh, how I am grateful for all those who have blessed families like mine by ministering with compassion.", "fr": "Oh, comme je suis reconnaissante envers tous ceux qui ont béni des familles comme la mienne en servant avec compassion.", "s": 106.32, "e": 112.6, "vocab": [["grateful", "reconnaissant"], ["compassion", "compassion"]]}, {"en": "I know the Lord is aware of you and your struggles as you strive to keep your covenants and minister to others.", "fr": "Je sais que le Seigneur te connaît, toi et tes difficultés, alors que tu t'efforces de respecter tes alliances et de servir les autres.", "s": 112.6, "e": 119.56, "vocab": [["struggles", "difficultés"], ["to strive", "s'efforcer"]]}, {"en": "He has promised blessings and divine help for you and your family as you exercise your faith to serve Him.", "fr": "Il a promis des bénédictions et une aide divine pour toi et ta famille si tu exerces ta foi pour le servir.", "s": 119.56, "e": 127.04, "vocab": [["to promise", "promettre"], ["faith", "foi"]]}, {"en": "We may not be able to fix difficult or heartbreaking circumstances as we hope;", "fr": "Nous ne pourrons peut-être pas réparer des situations difficiles ou déchirantes comme nous l'espérons ;", "s": 127.04, "e": 132.28, "vocab": [["to fix", "réparer"], ["heartbreaking", "déchirant"]]}, {"en": "some changes are not ours to make.", "fr": "certains changements ne dépendent pas de nous.", "s": 132.28, "e": 135.12, "vocab": [["some", "certains"]]}, {"en": "But we can choose to love and minister as the Savior would.", "fr": "Mais nous pouvons choisir d'aimer et de servir comme le Sauveur le ferait.", "s": 135.12, "e": 140.96, "vocab": [["to love", "aimer"], ["would", "ferait (conditionnel)"]]}]}, {"id": "l2p4", "num": 4, "title": "Une manière d'être", "sub": "Ni un programme, ni une liste", "emoji": "💛", "audio": "audio-lesson2.mp3", "dur": 60.2, "sentences": [{"en": "Ministering by the Spirit invites the Savior's healing into our lives and the lives of those we minister to.", "fr": "Servir par l'Esprit invite la guérison du Sauveur dans nos vies et dans celles des personnes que nous servons.", "s": 140.96, "e": 147.44, "vocab": [["healing", "guérison"], ["to invite", "inviter"]]}, {"en": "I often find peace, clarity, healing, and purpose when I minister.", "fr": "Je trouve souvent la paix, la clarté, la guérison et un but quand je sers.", "s": 147.44, "e": 153.48, "vocab": [["peace", "paix"], ["purpose", "but"]]}, {"en": "I find the Savior when I minister.", "fr": "Je trouve le Sauveur quand je sers.", "s": 153.48, "e": 156.44, "vocab": [["to find", "trouver"]]}, {"en": "This is by divine design.", "fr": "C'est un dessein divin.", "s": 156.44, "e": 159.6, "vocab": [["divine", "divin"], ["design", "dessein, plan"]]}, {"en": "Ministering is truly loving and caring for others as the Savior would.", "fr": "Servir, c'est véritablement aimer les autres et prendre soin d'eux comme le Sauveur le ferait.", "s": 159.6, "e": 164.16, "vocab": [["truly", "véritablement"], ["others", "les autres"]]}, {"en": "It is a way of being; it is the way of our Savior, Jesus Christ.", "fr": "C'est une manière d'être ; c'est la manière de notre Sauveur, Jésus-Christ.", "s": 164.16, "e": 168.96, "vocab": [["a way of being", "une manière d'être"]]}, {"en": "It is not a program or a checklist;", "fr": "Ce n'est ni un programme ni une liste de cases à cocher ;", "s": 168.96, "e": 171.76, "vocab": [["checklist", "liste à cocher"]]}, {"en": "ministering is the essence of who God is and who we can become as we follow Him.", "fr": "servir est l'essence de qui est Dieu et de qui nous pouvons devenir en le suivant.", "s": 171.76, "e": 178.12, "vocab": [["essence", "essence"], ["to follow", "suivre"]]}, {"en": "We are not called to or released from ministering.", "fr": "On n'est pas appelé à servir, ni relevé de servir.", "s": 178.12, "e": 181.4, "vocab": [["called", "appelé"], ["released", "relevé"]]}, {"en": "It is part of fulfilling the covenants we made at baptism and in the temple.", "fr": "Cela fait partie des alliances que nous avons faites au baptême et au temple.", "s": 181.4, "e": 185.8, "vocab": [["baptism", "baptême"], ["covenant", "alliance"]]}, {"en": "We covenanted to take upon us the Savior's name, becoming as He is as we sacrifice and consecrate our lives to Him.", "fr": "Nous avons fait alliance de prendre sur nous le nom du Sauveur, en devenant comme lui, en sacrifiant et en consacrant nos vies à lui.", "s": 185.8, "e": 193.96, "vocab": [["to sacrifice", "sacrifier"], ["to consecrate", "consacrer"]]}, {"en": "When we minister as He would, we begin to think, feel, and love as He would.", "fr": "Quand nous servons comme il le ferait, nous commençons à penser, à ressentir et à aimer comme lui.", "s": 193.96, "e": 201.12, "vocab": [["to think", "penser"], ["to feel", "ressentir"]]}]}, {"id": "l2p5", "num": 5, "title": "Un par un", "sub": "Le modèle du Sauveur", "emoji": "👤", "audio": "audio-lesson2.mp3", "dur": 44.5, "sentences": [{"en": "Our Father in Heaven carries out His eternal work by ministering to the individual needs of His children one by one.", "fr": "Notre Père céleste accomplit son œuvre éternelle en répondant aux besoins de chacun de ses enfants, un par un.", "s": 201.12, "e": 209.12, "vocab": [["one by one", "un par un"], ["eternal", "éternel"]]}, {"en": "The Savior showed us this pattern often during His mortal ministry as He compassionately blessed, healed, and cared for the one.", "fr": "Le Sauveur nous a souvent montré ce modèle pendant son ministère terrestre, en bénissant, guérissant et prenant soin de « la personne » avec compassion.", "s": 209.12, "e": 217.4, "vocab": [["pattern", "modèle"], ["to heal", "guérir"]]}, {"en": "He invites us to do likewise, to minister in individual and personal ways,", "fr": "Il nous invite à faire de même : servir de manière individuelle et personnelle,", "s": 217.4, "e": 221.96, "vocab": [["likewise", "de même"], ["personal", "personnel"]]}, {"en": "ways that help us to feel the love of God.", "fr": "des manières qui nous aident à ressentir l'amour de Dieu.", "s": 221.96, "e": 225.88, "vocab": [["love", "amour"]]}, {"en": "When we feel loved and seen by Him, it changes everything.", "fr": "Quand nous nous sentons aimés et vus par lui, tout change.", "s": 225.88, "e": 231.04, "vocab": [["seen", "vu"], ["everything", "tout"]]}, {"en": "And when we bless the one, we bless the whole.", "fr": "Et quand nous bénissons une personne, nous bénissons l'ensemble.", "s": 231.04, "e": 234.84, "vocab": [["to bless", "bénir"], ["the whole", "l'ensemble"]]}, {"en": "The Savior shows us the ultimate individuality of God's love through His atoning sacrifice", "fr": "Le Sauveur nous montre l'individualité ultime de l'amour de Dieu à travers son sacrifice expiatoire", "s": 234.84, "e": 240.76, "vocab": [["ultimate", "ultime"], ["sacrifice", "sacrifice"]]}, {"en": "and the divine capacity He has to heal and minister to you and me on an intimate level.", "fr": "et la capacité divine qu'il a de nous guérir et de nous servir, toi et moi, de manière intime.", "s": 240.76, "e": 245.64, "vocab": [["capacity", "capacité"], ["intimate", "intime"]]}]}, {"id": "l2p6", "num": 6, "title": "Comme je vous ai aimés", "sub": "Le commandement nouveau", "emoji": "❤️", "audio": "audio-lesson2.mp3", "dur": 71.6, "sentences": [{"en": "Jesus Christ chose to suffer for our sins and to atone in indescribable agony that we might be saved and receive divine succor.", "fr": "Jésus-Christ a choisi de souffrir pour nos péchés et d'expier dans une agonie indescriptible pour que nous puissions être sauvés et recevoir un secours divin.", "s": 245.64, "e": 256.12, "vocab": [["to suffer", "souffrir"], ["sins", "péchés"], ["succor", "secours"]]}, {"en": "All this He did without the assurance that we would love Him in return.", "fr": "Tout cela, il l'a fait sans l'assurance que nous l'aimerions en retour.", "s": 256.12, "e": 261.28, "vocab": [["assurance", "assurance"], ["in return", "en retour"]]}, {"en": "But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us.", "fr": "« Mais Dieu prouve son amour envers nous : lorsque nous étions encore pécheurs, Christ est mort pour nous. »", "s": 261.28, "e": 268.68, "vocab": [["yet", "encore"], ["to die", "mourir"]]}, {"en": "This is the kind of love He has for you and me.", "fr": "Voilà le genre d'amour qu'il a pour toi et moi.", "s": 268.68, "e": 272.64, "vocab": [["kind of", "genre de"]]}, {"en": "And this is the kind of love He desires us to have for each other:", "fr": "Et voilà le genre d'amour qu'il désire que nous ayons les uns pour les autres :", "s": 272.64, "e": 277.6, "vocab": [["to desire", "désirer"], ["each other", "les uns les autres"]]}, {"en": "A new commandment I give unto you, That ye love one another; as I have loved you.", "fr": "« Je vous donne un commandement nouveau : Aimez-vous les uns les autres ; comme je vous ai aimés. »", "s": 277.6, "e": 285.04, "vocab": [["commandment", "commandement"], ["new", "nouveau"]]}, {"en": "We can demonstrate our love for Him by keeping His commandments and ministering to others while they and we are yet imperfect.", "fr": "Nous pouvons lui montrer notre amour en respectant ses commandements et en servant les autres alors qu'eux et nous sommes encore imparfaits.", "s": 285.04, "e": 293.68, "vocab": [["to demonstrate", "montrer"], ["imperfect", "imparfait"]]}, {"en": "We've been sent here to learn to love God and each other as the Savior did,", "fr": "Nous avons été envoyés ici pour apprendre à aimer Dieu et à nous aimer comme le Sauveur l'a fait :", "s": 293.68, "e": 297.52, "vocab": [["sent", "envoyé"], ["to learn", "apprendre"]]}, {"en": "to love in sacrificial and transformational ways, ways that will bring our greatest happiness.", "fr": "aimer de manières sacrificielles et transformatrices, des manières qui apporteront notre plus grand bonheur.", "s": 297.52, "e": 304.0, "vocab": [["happiness", "bonheur"], ["greatest", "le plus grand"]]}, {"en": "Through the Savior's Atonement we can come to love in ways that may feel impossible.", "fr": "Grâce à l'Expiation du Sauveur, nous pouvons arriver à aimer de manières qui peuvent sembler impossibles.", "s": 304.0, "e": 310.16, "vocab": [["through", "grâce à"], ["impossible", "impossible"]]}, {"en": "Elder Quentin L. Cook taught, Our love of God and our fellow man is the ultimate test of the condition of our spirit.", "fr": "Quentin L. Cook a enseigné : « Notre amour de Dieu et de notre prochain est le test ultime de l'état de notre esprit. »", "s": 310.16, "e": 317.28, "vocab": [["fellow man", "prochain"], ["test", "épreuve, test"]]}]}, {"id": "l2p7", "num": 7, "title": "Choisir de servir", "sub": "« J'y vais — et ça se passe bien »", "emoji": "🌟", "audio": "audio-lesson2.mp3", "dur": 47.5, "sentences": [{"en": "Choosing to minister isn't always convenient or comfortable.", "fr": "Choisir de servir n'est pas toujours pratique ni confortable.", "s": 317.28, "e": 323.16, "vocab": [["convenient", "pratique"], ["comfortable", "confortable"]]}, {"en": "It requires sacrifice, faith, vulnerability, and trusting things will work out as we let God prevail.", "fr": "Cela demande du sacrifice, de la foi, de la vulnérabilité, et de faire confiance que tout s'arrangera si nous laissons Dieu prévaloir.", "s": 323.16, "e": 331.76, "vocab": [["vulnerability", "vulnérabilité"], ["to trust", "faire confiance"]]}, {"en": "When we pause and choose to care for someone over something,", "fr": "Quand nous faisons une pause et choisissons de nous occuper de quelqu'un plutôt que de quelque chose,", "s": 331.76, "e": 336.4, "vocab": [["to pause", "faire une pause"], ["someone", "quelqu'un"]]}, {"en": "His Spirit and love can enter in and we can receive the peace and perspective that we really need.", "fr": "son Esprit et son amour peuvent entrer, et nous recevons la paix et la perspective dont nous avons vraiment besoin.", "s": 336.4, "e": 344.48, "vocab": [["perspective", "perspective"], ["to need", "avoir besoin"]]}, {"en": "A young sister shared that she often feels nervous about ministering because she doesn't know how others will respond.", "fr": "Une jeune sœur a confié qu'elle est souvent nerveuse à l'idée de servir parce qu'elle ne sait pas comment les autres vont réagir.", "s": 344.48, "e": 350.76, "vocab": [["nervous", "nerveux"], ["to respond", "réagir"]]}, {"en": "I asked how she works through that.", "fr": "Je lui ai demandé comment elle surmonte cela.", "s": 350.76, "e": 353.32, "vocab": [["to work through", "surmonter"]]}, {"en": "She smiled and said, I go, and it usually turns out much better than I thought.", "fr": "Elle a souri et a dit : « J'y vais — et ça se passe généralement bien mieux que je ne le pensais. »", "s": 353.32, "e": 360.2, "vocab": [["to smile", "sourire"], ["usually", "généralement"]]}, {"en": "She exercises faith, and the Lord helps her.", "fr": "Elle exerce sa foi, et le Seigneur l'aide.", "s": 360.2, "e": 364.8, "vocab": [["to exercise", "exercer"]]}]}, {"id": "l2p8", "num": 8, "title": "Jamais seuls", "sub": "Le Seigneur sera avec nous", "emoji": "🤝", "audio": "audio-lesson2.mp3", "dur": 27.7, "sentences": [{"en": "As we minister in faith, we do not go alone.", "fr": "Quand nous servons avec foi, nous n'y allons pas seuls.", "s": 364.8, "e": 367.64, "vocab": [["alone", "seul"]]}, {"en": "The Lord will be with us.", "fr": "Le Seigneur sera avec nous.", "s": 367.64, "e": 369.08, "vocab": [["will be", "sera"]]}, {"en": "He will provide the means whereby we can accomplish the thing which he has commanded,", "fr": "Il « préparera le moyen d'accomplir la chose qu'il a commandée »,", "s": 369.08, "e": 373.76, "vocab": [["to provide", "fournir"], ["to accomplish", "accomplir"]]}, {"en": "including the blessing of God's priesthood power as we keep our covenants", "fr": "y compris la bénédiction du pouvoir de la prêtrise de Dieu quand nous respectons nos alliances,", "s": 373.76, "e": 377.56, "vocab": [["including", "y compris"], ["power", "pouvoir"]]}, {"en": "and His priesthood authority to represent Him through our assignment.", "fr": "et son autorité de la prêtrise pour le représenter à travers notre tâche.", "s": 377.56, "e": 381.56, "vocab": [["authority", "autorité"], ["to represent", "représenter"]]}, {"en": "The Lord knows the hearts of those we minister to.", "fr": "Le Seigneur connaît le cœur des personnes que nous servons.", "s": 381.56, "e": 385.12, "vocab": [["heart", "cœur"]]}, {"en": "He loves them and He loves you.", "fr": "Il les aime et il t'aime.", "s": 385.12, "e": 387.56, "vocab": [["them", "eux"]]}, {"en": "He will help you to bless them in the ways they need.", "fr": "Il t'aidera à les bénir de la manière dont elles ont besoin.", "s": 387.56, "e": 392.48, "vocab": [["ways", "manières"]]}]}, {"id": "l2p9", "num": 9, "title": "Une aide pour Dieu", "sub": "Sécher les larmes, fortifier", "emoji": "🙏", "audio": "audio-lesson2.mp3", "dur": 48.7, "sentences": [{"en": "Think of the significance of our ministering assignments.", "fr": "Pense à l'importance de nos tâches de service.", "s": 392.48, "e": 395.72, "vocab": [["significance", "importance"], ["assignment", "tâche, mission"]]}, {"en": "Relief Society and elders quorum presidencies receive revelation from the Lord to extend inspired assignments to you and me,", "fr": "Les présidences de la Société de Secours et du collège des anciens reçoivent la révélation du Seigneur pour nous confier des tâches inspirées, à toi et à moi :", "s": 395.72, "e": 403.12, "vocab": [["revelation", "révélation"], ["to extend", "confier"]]}, {"en": "assignments to represent Him and labor with Him in caring for God's children.", "fr": "des tâches pour le représenter et travailler avec lui en prenant soin des enfants de Dieu.", "s": 403.12, "e": 408.24, "vocab": [["to labor", "travailler"], ["children", "enfants"]]}, {"en": "As President Jeffrey R. Holland taught, we are invited to give the God and Father of us all a helping hand", "fr": "Comme l'a enseigné Jeffrey R. Holland, nous sommes invités à donner « au Dieu et Père de nous tous un coup de main", "s": 408.24, "e": 414.44, "vocab": [["helping hand", "coup de main"]]}, {"en": "with His staggering task of answering prayers, drying tears, and strengthening feeble knees.", "fr": "dans sa tâche immense de répondre aux prières, de sécher les larmes et de fortifier les genoux affaiblis. »", "s": 414.44, "e": 422.0, "vocab": [["tears", "larmes"], ["to dry", "sécher"], ["knees", "genoux"]]}, {"en": "If you want to feel grounded, gain a sense of divine belonging, and make a real difference in the world,", "fr": "Si tu veux te sentir ancré, ressentir une appartenance divine et faire une vraie différence dans le monde,", "s": 422.0, "e": 427.2, "vocab": [["grounded", "ancré"], ["belonging", "appartenance"]]}, {"en": "I invite you to follow the Savior and minister in His name.", "fr": "je t'invite à suivre le Sauveur et à servir en son nom.", "s": 427.2, "e": 431.68, "vocab": [["in His name", "en son nom"]]}, {"en": "Never was the need greater than now for souls to be lifted, strengthened, and healed through the Atonement of Jesus Christ.", "fr": "Jamais le besoin n'a été plus grand qu'aujourd'hui de voir des âmes relevées, fortifiées et guéries par l'Expiation de Jésus-Christ.", "s": 431.68, "e": 437.52, "vocab": [["souls", "âmes"], ["to lift", "relever"], ["to strengthen", "fortifier"]]}, {"en": "So many of us desperately need to feel of His love.", "fr": "« Tant d'entre nous ont désespérément besoin de ressentir son amour. »", "s": 437.52, "e": 441.16, "vocab": [["desperately", "désespérément"]]}]}, {"id": "l2p10", "num": 10, "title": "Aimer sans limite", "sub": "Servir tous, n'oublier personne", "emoji": "🌍", "audio": "audio-lesson2.mp3", "dur": 43.5, "sentences": [{"en": "As His disciples, you and I have the covenant blessing and responsibility to bring the Savior's love and relief to all of God's children.", "fr": "En tant que ses disciples, toi et moi avons la bénédiction et la responsabilité, par alliance, d'apporter l'amour et le réconfort du Sauveur à tous les enfants de Dieu.", "s": 441.16, "e": 450.96, "vocab": [["responsibility", "responsabilité"], ["relief", "réconfort"]]}, {"en": "When we offer His love and belonging to others, we will find it ourselves.", "fr": "Quand nous offrons son amour et son appartenance aux autres, nous les trouvons nous-mêmes.", "s": 450.96, "e": 455.6, "vocab": [["to offer", "offrir"], ["ourselves", "nous-mêmes"]]}, {"en": "The Savior promised, Whosoever will lose his life for my sake shall find it.", "fr": "Le Sauveur a promis : « Quiconque perdra sa vie à cause de moi la trouvera. »", "s": 455.6, "e": 461.56, "vocab": [["whosoever", "quiconque"], ["to lose", "perdre"]]}, {"en": "The Savior did not limit His ministering to His family and close associations.", "fr": "Le Sauveur n'a pas limité son service à sa famille et à ses proches.", "s": 461.56, "e": 467.56, "vocab": [["to limit", "limiter"], ["close", "proche"]]}, {"en": "He ministered to all and invites us to do the same.", "fr": "Il a servi tout le monde et nous invite à faire de même.", "s": 467.56, "e": 471.36, "vocab": [["everyone", "tout le monde"]]}, {"en": "We receive ministering assignments to grow our capacity to love others and to ensure no one is forgotten.", "fr": "Nous recevons des tâches de service pour développer notre capacité d'aimer les autres et pour veiller à ce que personne ne soit oublié.", "s": 471.36, "e": 476.88, "vocab": [["to ensure", "veiller à"], ["forgotten", "oublié"]]}, {"en": "We pray for them, care for their needs, and strengthen their faith in Jesus Christ.", "fr": "Nous prions pour eux, nous nous occupons de leurs besoins et nous fortifions leur foi en Jésus-Christ.", "s": 476.88, "e": 484.68, "vocab": [["to pray", "prier"]]}]}, {"id": "l2p11", "num": 11, "title": "Témoignage et joie", "sub": "La manière du ciel", "emoji": "🕊️", "audio": "audio-lesson2.mp3", "dur": 38.4, "sentences": [{"en": "I believe our Father in Heaven wants you to be happy.", "fr": "Je crois que notre Père céleste veut que tu sois heureux.", "s": 484.68, "e": 487.64, "vocab": [["to believe", "croire"], ["happy", "heureux"]]}, {"en": "He loves you.", "fr": "Il t'aime.", "s": 487.64, "e": 489.36, "vocab": [["He loves you", "il t'aime"]]}, {"en": "His work, including ministering, is designed to bring you and me the greatest joy we can experience.", "fr": "Son œuvre, y compris le service, est conçue pour nous apporter, à toi et à moi, la plus grande joie que nous puissions connaître.", "s": 489.36, "e": 496.08, "vocab": [["work", "œuvre"], ["joy", "joie"]]}, {"en": "I testify that ministering not only brings forth the blessings of heaven, it is the way of heaven.", "fr": "Je témoigne que servir non seulement « fait descendre les bénédictions du ciel », mais que c'est la manière du ciel.", "s": 496.08, "e": 502.2, "vocab": [["to testify", "témoigner"], ["heaven", "ciel"]]}, {"en": "I testify that Jesus Christ lives.", "fr": "Je témoigne que Jésus-Christ vit.", "s": 502.2, "e": 505.12, "vocab": [["to live", "vivre"]]}, {"en": "As we emulate His sacrifice by loving and ministering as He would, we will be blessed to find our own joy, healing, and relief in Him.", "fr": "Si nous imitons son sacrifice en aimant et en servant comme lui, nous serons bénis de trouver notre propre joie, notre guérison et notre réconfort en lui.", "s": 505.12, "e": 515.12, "vocab": [["to emulate", "imiter"], ["own", "propre"]]}, {"en": "We will become even as He is.", "fr": "Nous deviendrons même comme il est.", "s": 515.12, "e": 518.0, "vocab": [["even as", "même comme"]]}, {"en": "In the name of Jesus Christ, amen.", "fr": "Au nom de Jésus-Christ, amen.", "s": 518.0, "e": 523.04, "vocab": [["amen", "amen"]]}]}]},
{"id": "l3", "num": 3, "title": "Encounter at the Empty Tomb", "titleFr": "L'expérience du sépulcre vide", "speaker": "Dieter F. Uchtdorf", "role": "Président suppléant du Collège des douze apôtres", "source": "Conférence générale · Avril 2026", "theme": "Nous devons faire l'expérience du sépulcre vide, prendre conscience de ce qu'il implique, et, à notre tour, en rendre témoignage.", "parts": [{"id": "l3p1", "num": 1, "title": "Vers le tombeau", "sub": "Un petit groupe de femmes", "emoji": "🌒", "audio": "audio-lesson3.mp3", "dur": 38.0, "sentences": [{"en": "Nearly 2,000 years ago, a small group of women rose while it was still dark", "fr": "Il y a près de deux mille ans, un petit groupe de femmes s'est levé alors qu'il faisait encore nuit", "s": 6.8, "e": 14.96, "vocab": [["to rise (rose)", "se lever"], ["dark", "nuit, obscurité"]]}, {"en": "and made their way toward the tomb where the body of their beloved Lord, Jesus Christ, had been laid to rest.", "fr": "et s'est rendu au tombeau où le corps de leur Seigneur bien-aimé, Jésus-Christ, avait été déposé.", "s": 14.96, "e": 24.76, "vocab": [["tomb", "tombeau"], ["beloved", "bien-aimé"]]}, {"en": "I have tried to imagine the depth of their grief.", "fr": "J'ai essayé d'imaginer la profondeur de leur chagrin.", "s": 24.76, "e": 29.64, "vocab": [["grief", "chagrin, deuil"], ["depth", "profondeur"]]}, {"en": "I can't.", "fr": "Je n'y parviens pas.", "s": 29.64, "e": 31.76, "vocab": [["I can't", "je ne peux pas"]]}, {"en": "I have tried to imagine their heartache, helplessness, and hopelessness.", "fr": "J'ai essayé d'imaginer leur douleur, leur impuissance et leur désespoir.", "s": 31.76, "e": 36.88, "vocab": [["heartache", "douleur du cœur"], ["hopelessness", "désespoir"]]}, {"en": "I can't.", "fr": "Je n'y parviens pas.", "s": 36.88, "e": 37.64, "vocab": [["I can't", "je ne peux pas"]]}, {"en": "Perhaps the question they all asked was \"How could this happen?\"", "fr": "Peut-être que la question qu'elles se posaient toutes était : « Comment cela a-t-il pu arriver ? »", "s": 37.64, "e": 44.8, "vocab": [["perhaps", "peut-être"], ["to happen", "arriver, se produire"]]}]}, {"id": "l3p2", "num": 2, "title": "Comment a-t-il pu mourir ?", "sub": "La question sans réponse", "emoji": "💔", "audio": "audio-lesson3.mp3", "dur": 43.2, "sentences": [{"en": "How could the man who had cast out demons, healed the crippled, cured the sick,", "fr": "Comment cet homme qui avait chassé les démons, guéri les infirmes, soigné les malades,", "s": 44.8, "e": 51.04, "vocab": [["to heal", "guérir"], ["the sick", "les malades"]]}, {"en": "walked on water, conversed with angels,", "fr": "marché sur l'eau, conversé avec des anges,", "s": 51.04, "e": 53.92, "vocab": [["to walk on water", "marcher sur l'eau"], ["angel", "ange"]]}, {"en": "taught the blessed hope and infinite glory of the gospel,", "fr": "enseigné l'espérance divine et la gloire infinie de l'Évangile,", "s": 53.92, "e": 59.96, "vocab": [["hope", "espérance"], ["gospel", "Évangile"]]}, {"en": "fed multitudes, and raised the dead—", "fr": "nourri des foules et ressuscité les morts,", "s": 59.96, "e": 63.2, "vocab": [["to feed (fed)", "nourrir"], ["multitude", "foule"]]}, {"en": "how could He Himself have died?", "fr": "comment cet homme avait-il pu mourir ?", "s": 63.2, "e": 67.96, "vocab": [["to die", "mourir"]]}, {"en": "Today we understand better why the Savior had to die.", "fr": "Aujourd'hui, nous comprenons mieux pourquoi le Sauveur devait mourir.", "s": 67.96, "e": 74.12, "vocab": [["Savior", "Sauveur"], ["to understand", "comprendre"]]}, {"en": "We know His \"dying brought new birth through resurrection's miracle.\"", "fr": "Nous savons que « par sa mort, il a pu nous donner l'espoir miraculeux d'un jour ressusciter ».", "s": 74.12, "e": 78.88, "vocab": [["dying", "mort, le fait de mourir"], ["resurrection", "résurrection"]]}, {"en": "But did His disciples know this at the time?", "fr": "Mais ses disciples le savaient-ils à ce moment-là ?", "s": 78.88, "e": 82.52, "vocab": [["disciple", "disciple"], ["at the time", "à ce moment-là"]]}, {"en": "Or did they wonder if God had entirely abandoned them?", "fr": "Ou se demandaient-ils si Dieu les avait complètement abandonnés ?", "s": 82.52, "e": 87.96, "vocab": [["to wonder", "se demander"], ["to abandon", "abandonner"]]}]}, {"id": "l3p3", "num": 3, "title": "Par amour et révérence", "sub": "Pourquoi elles y sont allées", "emoji": "💛", "audio": "audio-lesson3.mp3", "dur": 60.3, "sentences": [{"en": "Despite the heaviness of their hearts and the unanswered questions in their minds,", "fr": "Malgré le poids qui pesait sur leur cœur et les questions sans réponse qui occupaient leur esprit,", "s": 87.96, "e": 95.4, "vocab": [["heaviness", "lourdeur, poids"], ["unanswered", "sans réponse"]]}, {"en": "Mary and her companions made their way to the tomb.", "fr": "Marie et ses compagnes se sont rendues au tombeau.", "s": 95.4, "e": 98.72, "vocab": [["companion", "compagne, compagnon"]]}, {"en": "They didn't come expecting a miracle.", "fr": "Elles n'y sont pas allées dans l'espoir de voir un miracle.", "s": 98.72, "e": 103.32, "vocab": [["to expect", "s'attendre à"], ["miracle", "miracle"]]}, {"en": "They didn't come anticipating their questions would be answered.", "fr": "Elles n'y sont pas allées dans l'espoir d'obtenir des réponses à leurs questions.", "s": 103.32, "e": 108.72, "vocab": [["to anticipate", "s'attendre à, prévoir"]]}, {"en": "They certainly didn't come because they had a complete understanding of what was happening.", "fr": "Elles n'y sont certainement pas allées parce qu'elles comprenaient parfaitement la situation.", "s": 108.72, "e": 114.64, "vocab": [["complete understanding", "compréhension totale"]]}, {"en": "They came because of their immeasurable love and reverence for Jesus Christ.", "fr": "Elles y sont allées par amour et par révérence infinis pour Jésus-Christ.", "s": 114.64, "e": 122.4, "vocab": [["immeasurable", "incommensurable, infini"], ["reverence", "révérence, respect"]]}, {"en": "They came desiring to provide a loving act of service", "fr": "Elles y sont allées animées du désir d'accomplir un geste de service aimant,", "s": 122.4, "e": 127.56, "vocab": [["act of service", "geste de service"], ["loving", "aimant"]]}, {"en": "as a measure of their devotion and love for the man they honored and followed as the promised Messiah.", "fr": "en témoignage de leur dévotion et de leur amour pour l'homme qu'elles honoraient et suivaient comme le Messie promis.", "s": 127.56, "e": 136.88, "vocab": [["devotion", "dévotion"], ["promised Messiah", "Messie promis"]]}, {"en": "They came because they knew when the world is dark,", "fr": "Elles y sont allées parce qu'elles savaient que, lorsque le monde est plongé dans l'obscurité,", "s": 136.88, "e": 141.64, "vocab": [["dark", "sombre, obscur"]]}, {"en": "the best place to go is toward \"the light that shines in darkness.\"", "fr": "le meilleur endroit où aller est vers « la lumière qui luit dans les ténèbres ».", "s": 141.64, "e": 148.24, "vocab": [["light", "lumière"], ["to shine", "briller, luire"]]}]}, {"id": "l3p4", "num": 4, "title": "La pierre roulée", "sub": "La découverte du tombeau vide", "emoji": "🪨", "audio": "audio-lesson3.mp3", "dur": 43.4, "sentences": [{"en": "What Mary and those with her discovered on that Sunday morning changed the world forever.", "fr": "Ce que Marie et celles qui l'accompagnaient ont découvert ce dimanche matin-là a changé le monde pour toujours.", "s": 148.24, "e": 155.0, "vocab": [["to discover", "découvrir"], ["forever", "pour toujours"]]}, {"en": "\"They found the stone rolled away from the tomb,", "fr": "« Elles ont découvert que la pierre avait été roulée de devant le tombeau ;", "s": 155.0, "e": 160.12, "vocab": [["stone", "pierre"], ["rolled away", "roulée (de côté)"]]}, {"en": "but when they went in they did not find the body of the Lord Jesus.", "fr": "elles sont entrées, mais elles n'ont pas trouvé le corps du Seigneur Jésus.", "s": 160.12, "e": 166.0, "vocab": [["body", "corps"], ["to find (found)", "trouver"]]}, {"en": "While they were perplexed about this, behold, two men stood by them in dazzling apparel", "fr": "Comme elles ne savaient que penser de cela, voici, deux hommes leur sont apparus, en habits resplendissants", "s": 166.0, "e": 174.72, "vocab": [["perplexed", "perplexe"], ["dazzling", "éblouissant, resplendissant"]]}, {"en": "and said to them, 'Why do you seek the living among the dead?", "fr": "et leur ont dit : Pourquoi cherchez-vous parmi les morts celui qui est vivant ?", "s": 174.72, "e": 180.08, "vocab": [["to seek", "chercher"], ["the living", "les vivants"]]}, {"en": "He is not here, but has risen.'\"", "fr": "Il n'est pas ici, mais il est ressuscité. »", "s": 180.08, "e": 184.84, "vocab": [["risen", "ressuscité"]]}, {"en": "This encounter at the empty tomb changed them forever.", "fr": "Cette expérience près du sépulcre vide les a transformées à jamais.", "s": 184.84, "e": 189.16, "vocab": [["encounter", "rencontre, expérience"], ["empty", "vide"]]}, {"en": "It changed the world.", "fr": "Elle a transformé le monde.", "s": 189.16, "e": 191.64, "vocab": [["to change", "changer, transformer"]]}]}, {"id": "l3p5", "num": 5, "title": "Il vit !", "sub": "Bien plus qu'un personnage historique", "emoji": "☀️", "audio": "audio-lesson3.mp3", "dur": 57.0, "sentences": [{"en": "Many might picture Jesus as a carpenter from Nazareth or a traveling preacher from Galilee.", "fr": "Beaucoup se représentent peut-être Jésus comme un charpentier de Nazareth ou un prédicateur itinérant de Galilée.", "s": 191.64, "e": 198.6, "vocab": [["carpenter", "charpentier"], ["preacher", "prédicateur"]]}, {"en": "They might note the significant influence He had on the world's religious history.", "fr": "Ils reconnaissent peut-être l'influence considérable qu'il a eue sur l'histoire religieuse du monde.", "s": 198.6, "e": 204.04, "vocab": [["significant", "considérable"], ["influence", "influence"]]}, {"en": "But the bold message of the empty tomb is that Jesus Christ is not merely a historical figure.", "fr": "Mais le message sûr du sépulcre vide est que Jésus-Christ n'est pas simplement un personnage historique.", "s": 204.04, "e": 214.76, "vocab": [["bold", "audacieux, assuré"], ["historical figure", "personnage historique"]]}, {"en": "We do not seek Him among the dead.", "fr": "Nous ne le cherchons pas parmi les morts.", "s": 214.76, "e": 217.16, "vocab": [["among", "parmi"], ["the dead", "les morts"]]}, {"en": "He is risen!", "fr": "Il est ressuscité !", "s": 217.16, "e": 218.84, "vocab": [["He is risen", "il est ressuscité"]]}, {"en": "We understand He is not confined to the pages of a book", "fr": "Nous comprenons qu'il n'est pas confiné aux pages d'un livre,", "s": 218.84, "e": 222.96, "vocab": [["confined", "confiné, limité"], ["page", "page"]]}, {"en": "any more than He was confined to that grave of stone.", "fr": "pas plus qu'il ne l'était à ce tombeau de pierre.", "s": 222.96, "e": 228.32, "vocab": [["grave", "tombe"], ["stone", "pierre"]]}, {"en": "The scriptures teach us not only who Jesus was but who He is.", "fr": "Les Écritures nous enseignent non seulement qui était Jésus, mais aussi qui il est.", "s": 228.32, "e": 236.44, "vocab": [["scriptures", "Écritures"], ["to teach", "enseigner"]]}, {"en": "Because of what happened on that Sunday morning, we can speak of Jesus Christ in the present tense.", "fr": "En vertu de ce qui s'est passé ce dimanche matin-là, nous parlons de Jésus-Christ au présent.", "s": 236.44, "e": 243.6, "vocab": [["present tense", "temps présent"]]}, {"en": "He lives!", "fr": "Il vit !", "s": 243.6, "e": 244.48, "vocab": [["He lives", "il vit"]]}, {"en": "Today.", "fr": "Aujourd'hui.", "s": 244.48, "e": 245.8, "vocab": [["today", "aujourd'hui"]]}, {"en": "At this moment.", "fr": "En ce moment même.", "s": 245.8, "e": 248.6, "vocab": [["at this moment", "en ce moment"]]}]}, {"id": "l3p6", "num": 6, "title": "Une influence vivante", "sub": "Sa force au quotidien", "emoji": "🕊️", "audio": "audio-lesson3.mp3", "dur": 35.7, "sentences": [{"en": "He lives and is an active, ongoing influence in His Church", "fr": "Il vit et exerce une influence active et continue dans son Église", "s": 248.6, "e": 254.56, "vocab": [["ongoing", "continu"], ["Church", "Église"]]}, {"en": "and in the personal lives of those who follow Him.", "fr": "et dans la vie personnelle de ceux qui le suivent.", "s": 254.56, "e": 257.44, "vocab": [["personal life", "vie personnelle"], ["to follow", "suivre"]]}, {"en": "He guides, comforts, listens, calms our fears, and wipes away our tears.", "fr": "Il nous guide, chasse notre tristesse, apaise nos craintes et calme notre cœur troublé.", "s": 257.44, "e": 265.36, "vocab": [["to comfort", "consoler"], ["to wipe away", "essuyer"]]}, {"en": "The message of the risen Christ is that, with His strength, all obstacles can be overcome.", "fr": "Le message du Christ ressuscité est qu'avec sa force, nous pouvons surmonter tous les obstacles.", "s": 265.36, "e": 274.12, "vocab": [["strength", "force"], ["to overcome", "surmonter"]]}, {"en": "Because Jesus Christ conquered death,", "fr": "Parce que Jésus-Christ a vaincu la mort,", "s": 274.12, "e": 277.4, "vocab": [["to conquer", "vaincre"], ["death", "mort"]]}, {"en": "surely He can conquer any danger, confusion, or doubt we face.", "fr": "il peut assurément vaincre tout danger, toute confusion ou tout doute auxquels nous sommes confrontés.", "s": 277.4, "e": 284.28, "vocab": [["surely", "assurément"], ["doubt", "doute"]]}]}, {"id": "l3p7", "num": 7, "title": "Les premières témoins", "sub": "Deux invitations", "emoji": "📣", "audio": "audio-lesson3.mp3", "dur": 56.2, "sentences": [{"en": "Heavenly messengers at the empty tomb gave Mary and her companions two invitations.", "fr": "Les messagers célestes, près du sépulcre vide, ont adressé deux invitations à Marie et à ses compagnes.", "s": 284.28, "e": 291.0, "vocab": [["heavenly messenger", "messager céleste"], ["invitation", "invitation"]]}, {"en": "First, \"Come, and see the place where the Lord lay.\"", "fr": "Premièrement : « Venez et voyez le lieu où il était couché. »", "s": 291.0, "e": 295.52, "vocab": [["come and see", "venez et voyez"], ["to lie (lay)", "être couché"]]}, {"en": "Second, \"Go quickly and tell His disciples that He is risen from the dead.\"", "fr": "Deuxièmement : « Allez promptement dire à ses disciples qu'il est ressuscité des morts. »", "s": 295.52, "e": 302.16, "vocab": [["quickly", "promptement, vite"], ["to tell", "dire, annoncer"]]}, {"en": "In time, the Savior echoed a similar invitation to all:", "fr": "Plus tard, le Sauveur a réitéré une invitation similaire à tous :", "s": 302.16, "e": 306.92, "vocab": [["in time", "avec le temps, plus tard"], ["to echo", "reprendre, faire écho"]]}, {"en": "\"Go into all the world and preach the gospel to every creature.\"", "fr": "« Allez dans le monde entier et prêchez la bonne nouvelle à toute la création. »", "s": 306.92, "e": 312.68, "vocab": [["to preach", "prêcher"], ["creature", "créature, création"]]}, {"en": "Those early believers did just that.", "fr": "C'est exactement ce qu'ont fait les premiers croyants.", "s": 312.68, "e": 317.2, "vocab": [["believer", "croyant"], ["just that", "exactement cela"]]}, {"en": "And soon, the good news of the Resurrection of Jesus Christ spread throughout \"all nations.\"", "fr": "Et bientôt, la bonne nouvelle de la résurrection de Jésus-Christ s'est répandue parmi « toutes les nations ».", "s": 317.2, "e": 327.92, "vocab": [["good news", "bonne nouvelle"], ["to spread", "se répandre"]]}, {"en": "That glorious work continues today", "fr": "Cette œuvre glorieuse se poursuit aujourd'hui encore,", "s": 327.92, "e": 331.24, "vocab": [["glorious", "glorieux"], ["to continue", "se poursuivre"]]}, {"en": "as we proclaim His way in word and deed throughout more than 150 countries.", "fr": "tandis que nous proclamons sa voie par nos paroles et nos actes dans plus de cent cinquante pays.", "s": 331.24, "e": 340.48, "vocab": [["word and deed", "en paroles et en actes"], ["country", "pays"]]}]}, {"id": "l3p8", "num": 8, "title": "Tout a commencé ce matin-là", "sub": "Faire de même", "emoji": "🌅", "audio": "audio-lesson3.mp3", "dur": 52.1, "sentences": [{"en": "But it's worth remembering how it started—", "fr": "Mais il est bon de se rappeler comment tout a commencé :", "s": 340.48, "e": 347.12, "vocab": [["worth remembering", "bon à rappeler"], ["to start", "commencer"]]}, {"en": "early on that Sunday morning with Mary and a small group of friends", "fr": "tôt ce dimanche matin, avec Marie et un petit groupe d'amies", "s": 347.12, "e": 351.72, "vocab": [["early", "tôt"], ["friend", "ami(e)"]]}, {"en": "who, despite grief, fear, and unanswered questions,", "fr": "qui, malgré leur chagrin, leur peur et leurs questions sans réponse,", "s": 351.72, "e": 356.48, "vocab": [["despite", "malgré"], ["fear", "peur"]]}, {"en": "encountered the empty tomb and learned for themselves the glorious truth of His Resurrection.", "fr": "ont découvert le tombeau vide et ont appris par elles-mêmes la glorieuse vérité de sa résurrection.", "s": 356.48, "e": 365.76, "vocab": [["for themselves", "par elles-mêmes"], ["truth", "vérité"]]}, {"en": "It began on that Easter morning when these few women became the world's first witnesses", "fr": "Tout a commencé ce matin de Pâques, lorsque ces quelques femmes sont devenues les premières témoins au monde", "s": 365.76, "e": 372.24, "vocab": [["Easter", "Pâques"], ["witness", "témoin"]]}, {"en": "of the single greatest event in the history of this world.", "fr": "du plus grand événement de l'histoire de ce monde.", "s": 372.24, "e": 377.4, "vocab": [["greatest", "le plus grand"], ["event", "événement"]]}, {"en": "We must all do the same.", "fr": "Nous devons tous faire de même.", "s": 377.4, "e": 381.24, "vocab": [["the same", "la même chose"]]}, {"en": "We must encounter the empty tomb, experience the reality of what it means,", "fr": "Nous devons faire l'expérience du sépulcre vide, prendre conscience de sa réalité et de ce qu'il implique,", "s": 381.24, "e": 387.0, "vocab": [["to experience", "faire l'expérience de"], ["reality", "réalité"]]}, {"en": "and, in turn, share that witness with others.", "fr": "et, à notre tour, en rendre témoignage.", "s": 387.0, "e": 392.56, "vocab": [["in turn", "à notre tour"], ["to share", "partager"]]}]}, {"id": "l3p9", "num": 9, "title": "Heureux ceux qui ont cru", "sub": "Nos propres expériences", "emoji": "🙏", "audio": "audio-lesson3.mp3", "dur": 44.7, "sentences": [{"en": "Even though centuries separate us from that holy day,", "fr": "Même si des siècles nous séparent de ce jour sacré,", "s": 392.56, "e": 397.92, "vocab": [["century", "siècle"], ["holy", "saint, sacré"]]}, {"en": "we are among those who Jesus referred to when He said,", "fr": "nous faisons partie de ceux auxquels Jésus faisait référence lorsqu'il a dit :", "s": 397.92, "e": 401.76, "vocab": [["to refer to", "faire référence à"]]}, {"en": "\"Blessed are those who have not seen and yet have believed.\"", "fr": "« Heureux ceux qui n'ont pas vu et qui ont cru ! »", "s": 401.76, "e": 409.88, "vocab": [["blessed", "heureux, bénis"], ["to believe", "croire"]]}, {"en": "The Savior has entrusted each of us personally with sacred spiritual experiences and knowledge.", "fr": "Le Sauveur a confié à chacun de nous individuellement des expériences et des connaissances spirituelles sacrées.", "s": 409.88, "e": 418.8, "vocab": [["to entrust", "confier"], ["knowledge", "connaissance"]]}, {"en": "Because of those experiences, we can see for ourselves the meaning of the empty tomb:", "fr": "Grâce à ces expériences, nous pouvons comprendre par nous-mêmes la signification du sépulcre vide :", "s": 418.8, "e": 427.0, "vocab": [["meaning", "signification"]]}, {"en": "that Jesus Christ lives and is actively blessing all who seek Him.", "fr": "Jésus-Christ vit et répand activement ses bénédictions sur tous ceux qui le recherchent.", "s": 427.0, "e": 437.28, "vocab": [["to bless", "bénir"], ["to seek", "rechercher"]]}]}, {"id": "l3p10", "num": 10, "title": "Répandre la bonne nouvelle", "sub": "Des actes plus forts que les mots", "emoji": "🌍", "audio": "audio-lesson3.mp3", "dur": 66.8, "sentences": [{"en": "We too can rise to Jesus's challenge and spread the glorious news of the empty tomb.", "fr": "Nous aussi, nous pouvons répondre à l'invitation de Jésus et faire connaître la bonne nouvelle du sépulcre vide.", "s": 437.28, "e": 446.12, "vocab": [["to rise to a challenge", "relever un défi"], ["to spread the news", "répandre la nouvelle"]]}, {"en": "We can serve full-time missions,", "fr": "Nous pouvons faire une mission à plein temps,", "s": 446.12, "e": 448.2, "vocab": [["full-time", "à plein temps"], ["mission", "mission"]]}, {"en": "which will bring lifelong blessings not only now but for generations to come.", "fr": "ce qui sera une source de bénédictions durables non seulement pour nous, mais aussi pour les générations à venir.", "s": 448.2, "e": 453.04, "vocab": [["lifelong", "de toute une vie, durable"], ["generation", "génération"]]}, {"en": "We can feel a renewed determination", "fr": "Nous pouvons éprouver une détermination renouvelée", "s": 453.04, "e": 456.88, "vocab": [["renewed", "renouvelé"], ["determination", "détermination"]]}, {"en": "and embrace the challenge of becoming lifelong missionaries and disciples of Christ", "fr": "et relever le défi de devenir des missionnaires et des disciples du Christ à vie", "s": 456.88, "e": 463.6, "vocab": [["to embrace", "adopter, embrasser"], ["challenge", "défi"]]}, {"en": "through courageous and humble acts of discipleship in our daily lives.", "fr": "en accomplissant quotidiennement des actes humbles et courageux, dignes de disciples du Sauveur.", "s": 463.6, "e": 470.0, "vocab": [["courageous", "courageux"], ["humble", "humble"]]}, {"en": "We can walk in \"the way\" of Christ and \"serve God with all diligence day and night.\"", "fr": "Nous pouvons marcher sur « le chemin » du Christ et « servir Dieu jour et nuit en toute diligence ».", "s": 470.0, "e": 476.56, "vocab": [["the way", "le chemin"], ["diligence", "diligence, zèle"]]}, {"en": "Living the message of the risen Christ testifies of our devotion and love for our Savior.", "fr": "Vivre selon le message du Christ ressuscité atteste de notre dévouement et de notre amour pour notre Sauveur.", "s": 476.56, "e": 486.36, "vocab": [["to testify", "témoigner, attester"], ["devotion", "dévouement"]]}, {"en": "It may well be that our consistent, courageous, and humble acts of service and love for God and His children", "fr": "Il se pourrait bien que nos actes de service et d'amour pour Dieu et ses enfants, accomplis avec constance, courage et humilité,", "s": 486.36, "e": 496.04, "vocab": [["consistent", "constant, régulier"], ["His children", "ses enfants"]]}, {"en": "will speak far more eloquently and powerfully than we ever could through words alone.", "fr": "soient bien plus éloquents et puissants que nos simples mots.", "s": 496.04, "e": 504.08, "vocab": [["eloquently", "avec éloquence"], ["powerful", "puissant"]]}]}, {"id": "l3p11", "num": 11, "title": "Marcher vers la lumière", "sub": "Malgré les questions", "emoji": "🔆", "audio": "audio-lesson3.mp3", "dur": 50.2, "sentences": [{"en": "Some might hesitate to commit fully", "fr": "Certains hésitent parfois à s'engager pleinement", "s": 504.08, "e": 508.16, "vocab": [["to hesitate", "hésiter"], ["to commit", "s'engager"]]}, {"en": "because of unresolved questions relating to life circumstances, the gospel, or the Church.", "fr": "en raison de questions non résolues concernant leur situation personnelle, l'Évangile ou l'Église.", "s": 508.16, "e": 516.32, "vocab": [["unresolved", "non résolu"], ["circumstances", "situation, circonstances"]]}, {"en": "But, like Mary and those with her that morning, even when things seem dark,", "fr": "Mais, comme Marie et les femmes qui l'accompagnaient ce matin-là, même lorsque tout semble sombre,", "s": 516.32, "e": 524.44, "vocab": [["to seem", "sembler"]]}, {"en": "we step forward in faith, with courage and humility, and walk toward the Savior's light.", "fr": "nous allons de l'avant avec foi, courage et humilité, et nous marchons vers la lumière du Sauveur.", "s": 524.44, "e": 532.36, "vocab": [["to step forward", "aller de l'avant"], ["faith", "foi"]]}, {"en": "As we do so, eventually the dawn of understanding will surely reward our faith.", "fr": "Si nous le faisons, l'aube de la compréhension récompensera assurément notre foi.", "s": 532.36, "e": 538.64, "vocab": [["dawn", "aube"], ["to reward", "récompenser"]]}, {"en": "Like the warmth and light of the morning sun,", "fr": "Aussi chaleureux et lumineux que le soleil du matin,", "s": 538.64, "e": 542.64, "vocab": [["warmth", "chaleur"], ["morning sun", "soleil du matin"]]}, {"en": "we will feel the love and healing of the Son of God.", "fr": "nous ressentirons l'amour et la guérison du Fils de Dieu.", "s": 542.64, "e": 550.64, "vocab": [["healing", "guérison"], ["Son of God", "Fils de Dieu"]]}, {"en": "Darkness will give way to eternal light.", "fr": "Les ténèbres céderont la place à la lumière éternelle.", "s": 550.64, "e": 554.24, "vocab": [["darkness", "ténèbres"], ["to give way", "céder la place"]]}]}, {"id": "l3p12", "num": 12, "title": "La lumière qui nous guide", "sub": "Le soleil levant", "emoji": "🧭", "audio": "audio-lesson3.mp3", "dur": 47.4, "sentences": [{"en": "My dear brothers and sisters, each morning let the daily rising sun remind us", "fr": "Mes chers frères et sœurs, chaque matin, laissons le soleil levant nous rappeler", "s": 554.24, "e": 560.72, "vocab": [["rising sun", "soleil levant"], ["to remind", "rappeler"]]}, {"en": "that Jesus Christ is the light that leads us through this life,", "fr": "que Jésus-Christ est la lumière qui nous guide tout au long de cette vie,", "s": 560.72, "e": 565.04, "vocab": [["to lead", "guider, mener"]]}, {"en": "through any valley of sorrow, over beautiful mountains of joy,", "fr": "à travers les vallées de la tristesse, par-delà les magnifiques montagnes de la joie", "s": 565.04, "e": 569.84, "vocab": [["valley", "vallée"], ["sorrow", "tristesse"]]}, {"en": "and across any ocean of uncertainty or temptation,", "fr": "et au-delà de tout océan d'incertitude ou de tentation,", "s": 569.84, "e": 575.56, "vocab": [["uncertainty", "incertitude"], ["temptation", "tentation"]]}, {"en": "safely back to our loving and merciful Father in Heaven.", "fr": "pour nous ramener sains et saufs auprès de notre Père céleste aimant et miséricordieux.", "s": 575.56, "e": 581.08, "vocab": [["safely", "en sécurité, sains et saufs"], ["merciful", "miséricordieux"]]}, {"en": "Brothers and sisters, as we desire to encounter Christ,", "fr": "Frères et sœurs, si nous désirons rencontrer le Christ,", "s": 581.08, "e": 587.2, "vocab": [["to desire", "désirer"], ["to encounter", "rencontrer"]]}, {"en": "we must eventually make our way to the empty tomb.", "fr": "nous devons nécessairement passer par l'expérience du sépulcre vide.", "s": 587.2, "e": 591.32, "vocab": [["eventually", "finalement, tôt ou tard"], ["to make one's way", "se rendre à"]]}, {"en": "We must come to know for ourselves the blessed words", "fr": "Nous devons connaître par nous-mêmes la portée de ces paroles bénies :", "s": 591.32, "e": 595.16, "vocab": [["blessed words", "paroles bénies"]]}, {"en": "\"Be not afraid, for Jesus, who was crucified, is not here.", "fr": "« Ne craignez pas ; Jésus, qui a été crucifié, n'est pas ici.", "s": 595.16, "e": 600.28, "vocab": [["be not afraid", "ne craignez pas"], ["crucified", "crucifié"]]}, {"en": "He is risen!\"", "fr": "Il est ressuscité ! »", "s": 600.28, "e": 601.68, "vocab": [["He is risen", "il est ressuscité"]]}]}, {"id": "l3p13", "num": 13, "title": "Un grand changement de cœur", "sub": "Ces paroles nous transforment", "emoji": "❤️", "audio": "audio-lesson3.mp3", "dur": 42.2, "sentences": [{"en": "Those words will change us.", "fr": "Ces paroles nous transformeront.", "s": 601.68, "e": 604.48, "vocab": [["to change", "changer, transformer"]]}, {"en": "They will inspire us to take upon ourselves the name of Christ.", "fr": "Elles nous inciteront à prendre sur nous le nom du Christ.", "s": 604.48, "e": 609.84, "vocab": [["to inspire", "inciter, inspirer"], ["to take upon", "prendre sur soi"]]}, {"en": "And from that moment on, the Light of Christ will begin to bloom within us.", "fr": "Et à partir de ce moment-là, la lumière du Christ commencera à rayonner en nous.", "s": 609.84, "e": 615.12, "vocab": [["to bloom", "fleurir, rayonner"], ["within us", "en nous"]]}, {"en": "It will, in time, bring about a mighty change in our hearts", "fr": "Avec le temps, elle produira un grand changement dans notre cœur", "s": 615.12, "e": 619.76, "vocab": [["mighty change", "grand changement"], ["heart", "cœur"]]}, {"en": "and bless us with a disposition to do good continually.", "fr": "et nous inspirera une disposition à faire continuellement le bien.", "s": 619.76, "e": 624.48, "vocab": [["disposition", "disposition"], ["to do good", "faire le bien"]]}, {"en": "Jesus Christ and His restored gospel are our strength.", "fr": "Jésus-Christ et son Évangile rétabli sont notre force.", "s": 624.48, "e": 631.04, "vocab": [["restored", "rétabli"], ["strength", "force"]]}, {"en": "Jesus Christ is our guide for making choices", "fr": "Jésus-Christ est notre guide pour faire les bons choix.", "s": 631.04, "e": 636.88, "vocab": [["guide", "guide"], ["choice", "choix"]]}, {"en": "and will bring joy and happiness in this life and extend into the eternities.", "fr": "Il nous apportera la joie et le bonheur dans cette vie et jusque dans les éternités.", "s": 636.88, "e": 643.84, "vocab": [["joy", "joie"], ["happiness", "bonheur"]]}]}, {"id": "l3p14", "num": 14, "title": "Qu'avons-nous vu ?", "sub": "Devenir témoins", "emoji": "👁️", "audio": "audio-lesson3.mp3", "dur": 26.1, "sentences": [{"en": "No, we were not with Mary on that blessed Easter morning.", "fr": "Non, nous n'étions pas avec Marie en ce matin béni de Pâques.", "s": 643.84, "e": 649.76, "vocab": [["blessed", "béni"]]}, {"en": "We did not see what she and the other women saw.", "fr": "Nous n'avons pas vu ce qu'elle et les autres femmes ont vu.", "s": 649.76, "e": 653.04, "vocab": [["to see (saw)", "voir"]]}, {"en": "But we can ask ourselves: What have we seen, felt, or experienced?", "fr": "Mais nous pouvons nous demander : qu'avons-nous vu, ressenti ou vécu ?", "s": 653.04, "e": 660.52, "vocab": [["to feel (felt)", "ressentir"], ["to experience", "vivre, éprouver"]]}, {"en": "Shall we not, therefore, become witnesses of Jesus Christ?", "fr": "N'avons-nous pas là des raisons de devenir des témoins de Jésus-Christ ?", "s": 660.52, "e": 666.28, "vocab": [["therefore", "donc, par conséquent"], ["witness", "témoin"]]}, {"en": "Shall we not share our love for Him with others?", "fr": "Ne devrions-nous pas communiquer notre amour pour lui aux autres ?", "s": 666.28, "e": 669.92, "vocab": [["to share", "partager, communiquer"]]}]}, {"id": "l3p15", "num": 15, "title": "Il est ressuscité !", "sub": "Le témoignage d'un apôtre", "emoji": "🌟", "audio": "audio-lesson3.mp3", "dur": 65.2, "sentences": [{"en": "My dear friends, on this holy Easter morning, I offer my witness: He is risen.", "fr": "Mes chers amis, en ce saint matin de Pâques, voici mon témoignage : il est ressuscité.", "s": 669.92, "e": 681.56, "vocab": [["to offer one's witness", "rendre témoignage"]]}, {"en": "I have stood at the entrance to the empty tomb", "fr": "Je me suis tenu à l'entrée du sépulcre vide", "s": 681.56, "e": 684.96, "vocab": [["entrance", "entrée"], ["to stand (stood)", "se tenir"]]}, {"en": "and seen with spiritual eyes the eternal truth", "fr": "et j'ai vu, de mes yeux spirituels, cette vérité éternelle :", "s": 684.96, "e": 689.24, "vocab": [["spiritual eyes", "yeux spirituels"], ["eternal", "éternel"]]}, {"en": "that Jesus Christ is not found among the dead but among the living.", "fr": "Jésus-Christ ne se trouve pas parmi les morts, mais parmi les vivants.", "s": 689.24, "e": 694.6, "vocab": [["among the living", "parmi les vivants"]]}, {"en": "He lives!", "fr": "Il vit !", "s": 694.6, "e": 696.36, "vocab": [["He lives", "il vit"]]}, {"en": "That testimony has made all the difference in my life.", "fr": "Ce témoignage a transformé ma vie.", "s": 696.36, "e": 702.4, "vocab": [["testimony", "témoignage"], ["all the difference", "toute la différence"]]}, {"en": "That encounter at the tomb will do the same for all who earnestly seek Him.", "fr": "Cette expérience au sépulcre aura le même effet pour tous ceux qui le cherchent sincèrement.", "s": 702.4, "e": 709.36, "vocab": [["earnestly", "sincèrement"]]}, {"en": "It will make a difference to you.", "fr": "Elle vous transformera.", "s": 709.36, "e": 711.88, "vocab": [["to make a difference", "changer les choses"]]}, {"en": "My dear friends, let us walk in His way as joyful and constant disciples of our beloved Savior, the Risen One,", "fr": "Mes chers amis, marchons sur son chemin en disciples joyeux et constants de notre Sauveur bien-aimé, le Ressuscité.", "s": 711.88, "e": 724.36, "vocab": [["joyful", "joyeux"], ["the Risen One", "le Ressuscité"]]}, {"en": "is my prayer and my blessing in the holy name of Jesus Christ, amen.", "fr": "C'est ma prière et ma bénédiction, au saint nom de Jésus-Christ. Amen.", "s": 724.36, "e": 735.16, "vocab": [["prayer", "prière"], ["blessing", "bénédiction"]]}]}]}];
